require_once __DIR__.'/../includes/admin_ui.php';
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM parents WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
