if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$pdo->prepare("UPDATE parents SET status='Inactive' WHERE id=?")->execute([$id]);audit($pdo,'delete','Deactivated parent #'.$id);go('parents.php','Parent deactivated');}
$rows=$pdo->query("SELECT * FROM parents ORDER BY id DESC")->fetchAll();
