foreach($rows as $r){echo '<tr><td><b>'.e(trim($r['first_name'].' '.$r['last_name'])).'</b></td><td>'.e($r['email']??'').'</td><td>'.e($r['phone']??'').'</td><td>'.e($r['address']??'').'</td><td><span class="badge '.($r['status']==='Active'?'success':'danger').'">'.e($r['status']).'</span></td><td class="actions-cell"><a class="btn light small" href="?edit='.$r['id'].'">Edit</a><a class="btn danger small" data-confirm="Deactivate this parent?" href="?delete='.$r['id'].'">Deactivate</a></td></tr>';}
echo '</tbody></table></div></div><div class="modal" id="parentModal"><div class="modal-box"><div class="modal-head"><h2>'.($edit?'Edit Parent':'Add Parent').'</h2><button class="close">×</button></div><form class="form" method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="id" value="'.e((string)($edit['id']??0)).'"><div class="form-grid"><label>First Name<input name="first_name" required value="'.e($edit['first_name']??'').'"></label><label>Last Name<input name="last_name" required value="'.e($edit['last_name']??'').'"></label><label>Email<input type="email" name="email" value="'.e($edit['email']??'').'"></label><label>Phone<input name="phone" value="'.e($edit['phone']??'').'"></label><label class="form-full">Address<textarea name="address" rows="3">'.e($edit['address']??'').'</textarea></label><label>Status<select name="status"><option>Active</option><option'.(($edit['status']??'')==='Inactive'?' selected':'').'>Inactive</option></select></label></div><div class="form-actions"><button type="button" class="btn light close">Cancel</button><button class="btn">'.($edit?'Update Parent':'Save Parent').'</button></div></form></div></div>';if($edit)echo '<script>document.getElementById("parentModal").classList.add("show")</script>';admin_end();